from lib import *
S = SS('p58')
steps = [
    step("页面用 IntersectionObserver 观察列表底部的哨兵元素:哨兵进入视口就加载下一页(每页 10 条、每条 100 px,共 10 页 100 条,视口 600 px)。打开页面后不滚动:条目数是 10,等 1.5 秒后还是 10,服务器只收到 1 次 /api/items 请求——页面一打开,空列表里的哨兵就在视口内,第一次回调就加载了第 1 页;加载完后哨兵被推到视口之外(页面总高度 1020 px),不滚动就不会再触发。", t=tl(S(1)), done=lidx(S(1), '打开后条目数 10'), b=bars([['打开后条目数', 10, '10'], ['等 1.5 秒后', 10, '10'], ['/api/items 请求', 1, '1']], 12, done=[0, 1, 2]), kv=KV([['不滚动', '只有第 1 页,10 条'], ['哨兵', '被推到视口外后不再触发'], ['页面总高度', '1020 px']], ['不滚动'])),
    step("一点一点往下滚(每次 300 px,滚完等 0.12 秒),连续 3 次条目数没增加就判定到底了:滚了 11 次,条目数只有 40,/api/items 请求 4 次,用时 1397 ms,页面没有出现结束标记——判定“到底了”太早了。每页内容 1000 px,滚 3 次(900 px)可能还没碰到哨兵,条目数自然没变,脚本却以为到头了。", t=tl(S(2)), done=lidx(S(2), '滚了 11 次'), b=bars([['抓到的条目', 40, '40'], ['实际总条目', 100, '100']], 100, mark=[0], done=[1]), kv=KV([['抓到', '40 / 100'], ['原因', '“连续 3 次没增长”的判定太早'], ['该怎么办', '滚到页面底部,而不是匀速滚']], ['原因'])),
    step("每次直接跳到页面底部(scrollTo 页面高度),等 0.15 秒,重复直到不再增加:跳了 11 次,条目数 100,/api/items 请求 10 次,用时 1741 ms,页面出现结束标记 END。每次都滚到底,哨兵一定会进入视口,每次触发一页;最后一页之后哨兵变成 END,不再增长。", t=tl(S(3)), done=lidx(S(3), '跳了 11 次'), b=bars([['条目数', 100, '100'], ['请求次数', 10, '10']], 100, done=[0, 1]), kv=KV([['滚到底部', '11 次,100 条'], ['请求', '10 次'], ['结束标记', 'END']], ['滚到底部'])),
    step("视口很高(3000 px)时,朴素写法(只在哨兵“进入”视口时加载一次)会卡住:不滚动等 1.5 秒,条目数 10,再滚动 2 次后还是 10,/api/items 请求共 1 次——加载第一页后哨兵仍在视口内,IntersectionObserver 只在“可见性变化”时回调,没有变化就不再触发;每次加载后重新 observe 的写法:不滚动等 1.5 秒后 40 条(填满了高视口),再滚动 8 次后 100 条,请求 10 次。", t=tl(S(4)), done=lidx(S(4), '修正:加载完成后重新 observe'), mark=lidx(S(4), '朴素'), b=bars([['朴素写法:最终条目', 10, '10'], ['重新 observe:最终条目', 100, '100']], 100, mark=[0], done=[1]), kv=KV([['朴素写法', '高视口下卡在 10 条'], ['重新 observe', '40 条后再滚动到 100 条'], ['原因', 'IntersectionObserver 只在可见性变化时回调']], ['原因'])),
    step("判断到底了的两种办法:用页面自己的结束标记(哨兵文字变成 END):956 ms 到底;用“条目数在 1.0 秒内不再增加”:2017 ms(两次独立加载,差约 1060 ms,其中包含那 1.0 秒静默期);两者都得到 100 条。有结束标记就用结束标记,没有才用静默期,并要保证静默期比一次加载的最长耗时更长。", t=tl(S(5)), done=lidx(S(5), '用结束标记判断'), b=bars([['结束标记判断 ms', 956, '956'], ['静默期判断 ms', 2017, '2017']], 2100, done=[0], mark=[1]), kv=KV([['结束标记', '956 ms'], ['静默期 1.0 秒', '2017 ms'], ['静默期的前提', '要大于一次加载的最长耗时']], ['静默期的前提'])),
]
A = mkartp('p58', 58, '爬虫,无限滚动,IntersectionObserver,CDP,动态加载,headless Chrome,Python,真实验证,动画演示',
    '在本机用 IntersectionObserver 做的无限滚动页面上实测:不滚动只有第 1 页(10 条);匀速滚动并用“连续 3 次没增长”判定到底会在第 40 条提前停下;每次滚到底部拿到全部 100 条(10 次请求);3000 px 的高视口下朴素写法卡在 10 条,加载后重新 observe 才能继续。',
    '无限滚动的页面,HTML 里只有第一屏的数据,其余要滚动才会加载。爬虫怎么滚、什么时候停、遇到视口很高时为什么会卡住?这篇用一个本机的无限滚动页面和 CDP 逐个试。',
    [('10 / 40 / 100', '不滚动 / 匀速滚动并用“3 次没增长”判到底 / 每次滚到底部 时抓到的条目数(总共 100)'), ('10 对 100', '高视口(3000 px)下朴素写法与重新 observe 写法最终的条目数'), ('956 对 2017 ms', '用结束标记判断到底 与 用 1.0 秒静默期判断到底 的耗时')],
    [('不滚动', '<p>页面打开时只有第一页数据,哨兵被推到视口外之后不再触发。HTML 解析或 requests 只能拿到这一页(见第 54 篇)。</p>'),
     ('匀速滚动容易提前停', '<p>匀速滚动加“连续几次没增长就停”很容易提前停下:我的例子里每页 1000 px,滚 3 次 300 px 还没碰到哨兵,就在 40 条停了(100 条里只抓到 40 条)。</p>'),
     ('每次滚到底部', '<p>每次滚到页面底部更可靠,哨兵一定会进入视口:11 次滚动拿到全部 100 条,10 次请求,最后出现结束标记。</p>'),
     ('高视口的坑', '<p>IntersectionObserver 在元素的可见性发生变化时才回调。如果加载完一页后哨兵仍在视口内(视口很高),就不会再有回调,页面卡住——这是页面自己的 bug,但也会让爬虫拿不到数据。页面如果每次加载后重新 observe 就不会卡。</p>'),
     ('到底了', '<p>能读到页面的结束标记(例子里哨兵变成 END)就用它。只能靠“条目数在静默期内不再增长”判断时,静默期要比一次加载的最长耗时长,否则会和第二节一样提前停下。</p>')],
    steps,
    [ENV_P + '。页面是本机服务器上的一个小页面:列表加哨兵,IntersectionObserver 观察哨兵,进入视口就 fetch 下一页(服务器每次延迟 0.08 秒),共 10 页每页 10 条每条 100 px;Chrome 154 通过 pcdp.py 控制,用 Emulation.setDeviceMetricsOverride 设置视口(600 px 和 3000 px),用 window.scrollTo 滚动,数条目数;各情形各跑一次',
     '没有验证:真实站点的无限滚动(有的用滚动事件而不是 IntersectionObserver,有的按偏移量请求);用 CDP 的 Input.dispatchMouseEvent(mouseWheel) 模拟真实滚轮;“加载更多”按钮式的翻页;虚拟列表(只渲染可见的行,滚过的行会被移除)里抓取全部数据的办法;滚动触发的请求被限速时的处理'],
    '无限滚动')
